using Shortener.Core;
using Shortener.Core.Ports;

namespace Shortener.Infrastructure;

public class InMemoryLinkRepository : ILinkRepository
{
    private readonly ConcurrentDictionary<string, Link> _linksByShortCode = new();
    private readonly ConcurrentDictionary<string, string> _linksByLongUrl = new(); // Stores longUrl -> shortCode
    private readonly ConcurrentDictionary<string, int> _usageCounts = new();

    public Task<Link?> FindByShortCodeAsync(string shortCode)
    {
        if (_linksByShortCode.TryGetValue(shortCode, out var link))
        {
            _usageCounts.TryGetValue(shortCode, out var count); // `count` will be 0 if key not found
            return Task.FromResult<Link?>(link with { UsageCount = count });
        }
        return Task.FromResult<Link?>(null);
    }

    public Task<Link?> FindByLongUrlAsync(string longUrl)
    {
        if (_linksByLongUrl.TryGetValue(longUrl, out var shortCode))
        {
            if (_linksByShortCode.TryGetValue(shortCode, out var link))
            {
                _usageCounts.TryGetValue(shortCode, out var count); // `count` will be 0 if key not found
                return Task.FromResult<Link?>(link with { UsageCount = count });
            }
        }
        return Task.FromResult<Link?>(null);
    }

    public Task SaveAsync(Link link)
    {
        if (!_linksByShortCode.TryAdd(link.ShortCode, link with { UsageCount = 0 })) // Store initial link with 0 usage
        {
            throw new InvalidOperationException($"Short code '{link.ShortCode}' already exists.");
        }
        _linksByLongUrl.TryAdd(link.LongUrl, link.ShortCode);
        _usageCounts.TryAdd(link.ShortCode, 0); // Initialize usage count to 0
        return Task.CompletedTask;
    }

    public Task IncrementUsageCountAsync(string shortCode)
    {
        if (!_linksByShortCode.ContainsKey(shortCode))
        {
            throw new LinkNotFoundException(shortCode);
        }

        _usageCounts.AddOrUpdate(
            shortCode,
            _ => 1, // Should not happen if ContainsKey check passes, but for completeness
            (key, existingCount) => existingCount + 1
        );
        return Task.CompletedTask;
    }

    public void Clear()
    {
        _linksByShortCode.Clear();
        _linksByLongUrl.Clear();
        _usageCounts.Clear();
    }
}
